import {defaults,PRESETS,dimensions,validateSettings,renderDesign,inspectDesign,createCanvas,makePreview,layoutSheet,mmToPx,blobFromCanvas,pngBytes,makeZip,makePdf} from './engine.js';
const $=id=>document.getElementById(id),canvas=$('editor'),ctx=canvas.getContext('2d');
let settings=defaults(),assets=[],activeId=null,guides=true,mock=false,busy=false,undoStack=[],saveTimer,toastTimer,restoring=false;
const transforms=['scale','rotation','x','y'];
const fields={'width':'width','height':'height','bleed':'bleed','safe':'safe','scale':'scale','rotation':'rotation','offset-x':'x','offset-y':'y','background':'background','border-color':'borderColor','border':'border','caption':'caption','font-size':'fontSize','text-color':'textColor','text-y':'textY','dpi':'dpi','quantity':'quantity','paper':'paper','paper-width':'paperWidth','paper-height':'paperHeight','margin':'margin','gap':'gap'};
const selected=()=>assets.find(a=>a.id===activeId);
const current=()=>({...settings,...selected()?.transform});
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),4200);}
function serialize(){return{format:'guzi-workshop',version:1,settings,activeId,assets:assets.map(({id,name,src,transform})=>({id,name,src,transform}))};}
function checkpoint(){undoStack.push(JSON.stringify(serialize()));if(undoStack.length>25)undoStack.shift();$('undo').disabled=false;}
async function imageFrom(src){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('无法读取图片'));img.src=src;});}
function fileData(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('读取文件失败'));reader.readAsDataURL(file);});}
const database=new Promise((resolve,reject)=>{if(!window.indexedDB){reject(Error('此浏览器不支持本地保存'));return;}const req=indexedDB.open('guzi-workshop',1);req.onupgradeneeded=()=>req.result.createObjectStore('projects');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});database.catch(()=>{});
async function dbAction(mode,operation){const db=await database;return new Promise((resolve,reject)=>{const tx=db.transaction('projects',mode),req=operation(tx.objectStore('projects'));let result;req.onsuccess=()=>{result=req.result;};tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('保存被取消'));});}
function scheduleSave(){if(restoring)return;clearTimeout(saveTimer);$('save-state').textContent='正在保存到此设备…';saveTimer=setTimeout(async()=>{try{await dbAction('readwrite',store=>store.put(serialize(),'current'));$('save-state').textContent='已保存在此设备';}catch{$('save-state').textContent='本地保存失败，请下载项目';}},600);}
function presetOptions(){const items=PRESETS[settings.type];$('preset').replaceChildren(...items.map(([label,w,h],i)=>{const o=document.createElement('option');o.value=i;o.textContent=label;return o;}));const o=document.createElement('option');o.value='custom';o.textContent='自定义尺寸';$('preset').append(o);syncPreset();}
function syncPreset(){const i=PRESETS[settings.type].findIndex(([,w,h])=>w===settings.width&&h===settings.height);$('preset').value=i<0?'custom':String(i);}
function syncControls(){const s=current();for(const[id,key]of Object.entries(fields))$(id).value=s[key];$('height').disabled=settings.type==='badge';$('custom-paper').hidden=settings.paper!=='custom';$('scale-value').textContent=`${s.scale}%`;$('rotation-value').textContent=`${s.rotation}°`;$('border-value').textContent=`${s.border} mm`;$('text-y-value').textContent=`${s.textY}%`;for(const el of document.querySelectorAll('[data-template]'))el.classList.toggle('active',el.dataset.template===s.type);syncPreset();}
function renderAssets(){const list=$('asset-list');list.replaceChildren();for(const asset of assets){const wrap=document.createElement('div');wrap.style.position='relative';const button=document.createElement('button');button.className='asset'+(asset.id===activeId?' active':'');button.title=asset.name;button.style.width='100%';const img=document.createElement('img');img.src=asset.src;img.alt=asset.name;const label=document.createElement('span');label.textContent=asset.name;button.append(img,label);button.onclick=()=>{activeId=asset.id;renderAssets();syncControls();draw();scheduleSave();};const remove=document.createElement('button');remove.className='asset-remove';remove.textContent='×';remove.setAttribute('aria-label',`删除素材 ${asset.name}`);remove.onclick=()=>{checkpoint();assets=assets.filter(a=>a.id!==asset.id);if(activeId===asset.id)activeId=assets[0]?.id??null;renderAssets();syncControls();draw();scheduleSave();};wrap.append(button,remove);list.append(wrap);} $('asset-count').textContent=`${assets.length} 张素材`;}
function draw(){const s=current(),d=dimensions(s);canvas.width=mock?1000:Math.round(800*d.width/Math.max(d.width,d.height));canvas.height=mock?1000:Math.round(800*d.height/Math.max(d.width,d.height));ctx.clearRect(0,0,canvas.width,canvas.height);const a=selected();if(mock&&a){const preview=makePreview(s,a.img);ctx.drawImage(preview,0,0,canvas.width,canvas.height);}else renderDesign(ctx,s,a?.img,{guides});$('empty-state').hidden=!!a;$('artboard-wrap').style.aspectRatio=mock?'1':`${d.width}/${d.height}`;$('canvas-label').textContent=`${s.width}${s.type==='badge'?'':` × ${s.height}`} MM ${s.type==='badge'?'BADGE':s.type==='photo'?'PHOTO CARD':'STICKER'}`;$('canvas-dpi').textContent=`${s.dpi} DPI`;$('physical-size').textContent=`${d.width} × ${d.height} mm（含出血）`;$('interaction-hint').textContent=mock?'成品效果示意 · 制作参数请以厂家为准':'拖动图片调整构图 · 滚轮缩放 · 方向键微调';$('edit-view').classList.toggle('selected',!mock);$('mock-view').classList.toggle('selected',mock);const measure=(text,size)=>{ctx.save();ctx.font=`600 ${size}px "Noto Sans SC",system-ui,sans-serif`;const width=ctx.measureText(text).width;ctx.restore();return width;};const checks=inspectDesign(s,a?.img,measure);$('checks').replaceChildren(...checks.map(c=>{const li=document.createElement('li');li.className=c.level;li.textContent=(c.level==='good'?'✓ ':c.level==='warn'?'! ':'· ')+c.text;return li;}));$('check-summary').textContent=a?checks.some(c=>c.level==='warn')?'有项目需要确认':'尺寸已就绪':'等待图片';$('project-status').textContent=a?`${a.name} · ${a.img.width} × ${a.img.height} px`:'支持 PNG / JPG / WebP · 本地处理';for(const id of ['export-top','export-png','export-pdf','export-batch','export-preview'])$(id).disabled=!a||busy;}
function refresh(){syncControls();draw();scheduleSave();}
function updateField(id,commit=true){const key=fields[id],el=$(id),s=current(),string=['background','borderColor','caption','textColor','paper'].includes(key);if(el.type==='number'&&el.value===''){if(commit)syncControls();return;}const value=string?el.value:Number(el.value);const next={...s,[key]:value};if(key==='width'&&s.type==='badge')next.height=value;try{validateSettings(next);}catch(e){if(commit){toast(e.message);syncControls();}return;}if(transforms.includes(key)&&selected())selected().transform={...selected().transform,[key]:value};else{settings[key]=value;if(key==='width'&&s.type==='badge')settings.height=value;}refresh();}
for(const id of Object.keys(fields)){const el=$(id);el.addEventListener('focus',checkpoint);el.addEventListener('input',()=>updateField(id,el.type!=='number'));if(el.type==='number')el.addEventListener('change',()=>updateField(id));}
for(const button of document.querySelectorAll('[data-template]'))button.onclick=()=>{checkpoint();settings.type=button.dataset.template;const[,w,h]=PRESETS[settings.type][0];settings.width=w;settings.height=h;settings.caption='';settings.textY=settings.type==='photo'?91:82;for(const a of assets)a.transform={scale:100,rotation:0,x:0,y:0};presetOptions();refresh();};
$('preset').onchange=()=>{if($('preset').value==='custom')return;checkpoint();const[,w,h]=PRESETS[settings.type][Number($('preset').value)];settings.width=w;settings.height=h;refresh();};
for(const b of document.querySelectorAll('[data-color]'))b.onclick=()=>{checkpoint();settings.background=b.dataset.color;refresh();};
$('fit').onclick=()=>{checkpoint();if(selected())selected().transform={scale:100,rotation:0,x:0,y:0};else Object.assign(settings,{scale:100,rotation:0,x:0,y:0});refresh();};
$('guides').onclick=()=>{guides=!guides;$('guides').classList.toggle('selected',guides);$('guides').setAttribute('aria-pressed',String(guides));draw();};
$('edit-view').onclick=()=>{mock=false;draw();};$('mock-view').onclick=()=>{mock=true;draw();};
let drag;
canvas.addEventListener('pointerdown',e=>{if(!selected()||mock)return;checkpoint();drag={pointer:e.pointerId,x:e.clientX,y:e.clientY,base:{...current()}};canvas.setPointerCapture(e.pointerId);});
canvas.addEventListener('pointermove',e=>{if(!drag||drag.pointer!==e.pointerId)return;const rect=canvas.getBoundingClientRect(),d=dimensions(settings);const x=Math.max(-100,Math.min(100,drag.base.x+(e.clientX-drag.x)/rect.width*d.width/settings.width*100)),y=Math.max(-100,Math.min(100,drag.base.y+(e.clientY-drag.y)/rect.height*d.height/settings.height*100));selected().transform={...selected().transform,x:Math.round(x*10)/10,y:Math.round(y*10)/10};syncControls();draw();});
const stopDrag=()=>{if(drag){drag=null;scheduleSave();}};canvas.addEventListener('pointerup',stopDrag);canvas.addEventListener('pointercancel',stopDrag);
let wheelTimer;canvas.addEventListener('wheel',e=>{if(!selected()||mock)return;e.preventDefault();if(!wheelTimer)checkpoint();clearTimeout(wheelTimer);wheelTimer=setTimeout(()=>{wheelTimer=null;},300);selected().transform={...selected().transform,scale:Math.round(Math.max(50,Math.min(400,current().scale-e.deltaY*.08)))};refresh();},{passive:false});
canvas.addEventListener('keydown',e=>{const moves={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]};if(!selected()||mock||!moves[e.key])return;e.preventDefault();checkpoint();const[x,y]=moves[e.key],s=current(),step=e.shiftKey?5:1;selected().transform={...selected().transform,x:Math.max(-100,Math.min(100,s.x+x*step)),y:Math.max(-100,Math.min(100,s.y+y*step))};refresh();});
async function addFiles(files){if(busy)return;const allowed=[...files].filter(f=>['image/png','image/jpeg','image/webp'].includes(f.type));if(!allowed.length){toast('请选择 PNG、JPG 或 WebP 图片');return;}if(assets.length+allowed.length>20){toast('每个项目最多放入 20 张素材');return;}checkpoint();let count=0;for(const file of allowed){try{if(file.size>20*1024*1024)throw Error(`${file.name} 超过 20 MB`);const src=await fileData(file),img=await imageFrom(src);if(img.width*img.height>40000000)throw Error(`${file.name} 像素过大，请先缩小图片`);const asset={id:crypto.randomUUID(),name:file.name,src,img,transform:{scale:100,rotation:0,x:0,y:0}};assets.push(asset);activeId=asset.id;count++;}catch(e){toast(e.message);}}renderAssets();refresh();if(count)toast(`已放入 ${count} 张素材`);$('image-input').value='';}
for(const id of ['upload-button','empty-upload'])$(id).onclick=()=>$('image-input').click();$('image-input').onchange=e=>addFiles(e.target.files);
for(const area of [$('drop-zone'),$('upload-button')]){area.addEventListener('dragover',e=>{e.preventDefault();area.classList.add('dragover');});area.addEventListener('dragleave',()=>area.classList.remove('dragover'));area.addEventListener('drop',e=>{e.preventDefault();area.classList.remove('dragover');addFiles(e.dataTransfer.files);});}
$('sample-button').onclick=async()=>{try{if(assets.length>=20)throw Error('每个项目最多放入 20 张素材');const r=await fetch('sample.png');if(!r.ok)throw Error('示例图片加载失败');const b=await r.blob();await addFiles([new File([b],'星野 · 原创示例.png',{type:'image/png'})]);}catch(e){toast(e.message);}};
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}
function baseName(name){return name.replace(/\.[^.]+$/,'').replace(/[\\/:*?"<>|]/g,'_').slice(0,60)||'作品';}
async function exporting(action){if(busy||!selected())return;busy=true;draw();toast('正在准备导出…');try{await document.fonts.ready;validateSettings(current());await action();toast('导出完成，请查看下载文件');}catch(e){console.error(e);toast(e.message||'导出失败，请减小尺寸后重试');}finally{busy=false;draw();}}
const exportPng=()=>exporting(async()=>{const s=current();download(new Blob([await pngBytes(createCanvas(s,selected().img),s.dpi)],{type:'image/png'}),`${baseName(selected().name)}_${s.width}x${s.height}mm_${s.dpi}dpi.png`);});$('export-png').onclick=exportPng;$('export-top').onclick=exportPng;
$('export-preview').onclick=()=>exporting(async()=>{download(await blobFromCanvas(makePreview(current(),selected().img)),`${baseName(selected().name)}_成品预览.png`);});
$('export-batch').onclick=()=>exporting(async()=>{const files=[];for(let i=0;i<assets.length;i++){const a=assets[i],s={...settings,...a.transform};files.push({name:`${String(i+1).padStart(2,'0')}_${baseName(a.name)}_${s.dpi}dpi.png`,data:await pngBytes(createCanvas(s,a.img),s.dpi)});await new Promise(r=>setTimeout(r,0));}files.push({name:'制作参数.json',data:new TextEncoder().encode(JSON.stringify({settings,colorSpace:'RGB',units:'mm',assets:assets.map(a=>({name:a.name,transform:a.transform}))},null,2))});download(makeZip(files),'谷子工坊_全部制作稿.zip');});
function cropMarks(ctx,s,x,y,px){const left=x+s.bleed,right=left+s.width,top=y+s.bleed,bottom=top+s.height;ctx.save();ctx.strokeStyle='#666';ctx.lineWidth=.15*px;ctx.beginPath();const gap=.6,len=Math.min(2.2,Math.max(0,s.bleed-gap));if(len>0)for(const[cx,cy,dx,dy]of[[left,top,-1,-1],[right,top,1,-1],[left,bottom,-1,1],[right,bottom,1,1]]){ctx.moveTo((cx+dx*gap)*px,cy*px);ctx.lineTo((cx+dx*(gap+len))*px,cy*px);ctx.moveTo(cx*px,(cy+dy*gap)*px);ctx.lineTo(cx*px,(cy+dy*(gap+len))*px);}ctx.stroke();if(s.type==='badge'){ctx.strokeStyle='#ccc';ctx.setLineDash([px*.8,px*.8]);ctx.beginPath();ctx.ellipse((left+s.width/2)*px,(top+s.height/2)*px,s.width/2*px,s.height/2*px,0,0,Math.PI*2);ctx.stroke();}ctx.restore();}
$('export-pdf').onclick=()=>exporting(async()=>{const s=current(),jobs=assets.flatMap(a=>Array.from({length:s.quantity},()=>a)),layout=layoutSheet(s,jobs.length);if(layout.pages>100)throw Error('拼版页数超过 100 页，请减少数量');const pw=mmToPx(layout.paperWidth,s.dpi),ph=mmToPx(layout.paperHeight,s.dpi);if(pw*ph>24000000)throw Error('纸张像素过大，请降低 DPI 或减小纸张');const d=dimensions(s),pages=[];for(let page=0;page<layout.pages;page++){const sheet=document.createElement('canvas');sheet.width=pw;sheet.height=ph;const sc=sheet.getContext('2d');sc.fillStyle='#fff';sc.fillRect(0,0,pw,ph);const px=s.dpi/25.4;for(let i=0;i<jobs.length;i++){const pos=layout.positions[i];if(pos.page!==page)continue;const a=jobs[i],design=createCanvas({...s,...a.transform},a.img);sc.drawImage(design,pos.x*px,pos.y*px,d.width*px,d.height*px);cropMarks(sc,s,pos.x,pos.y,px);}pages.push({width:pw,height:ph,bytes:new Uint8Array(await(await blobFromCanvas(sheet,'image/jpeg')).arrayBuffer())});await new Promise(r=>setTimeout(r,0));}download(makePdf(pages,layout.paperWidth,layout.paperHeight),`谷子工坊_拼版_${layout.pages}页.pdf`);});
$('save-project').onclick=()=>{download(new Blob([JSON.stringify(serialize())],{type:'application/json'}),'我的谷子.guzi');toast('项目已下载，包含图片和编辑参数');};
$('load-project').onclick=()=>$('project-input').click();
async function restore(data){if(data?.format!=='guzi-workshop'||data.version!==1||!Array.isArray(data.assets)||data.assets.length>20)throw Error('不是有效的谷子工坊项目文件');const next=validateSettings(data.settings),loaded=[];for(const a of data.assets){if(typeof a.name!=='string'||typeof a.id!=='string'||typeof a.src!=='string'||a.src.length>30000000||!/^data:image\/(png|jpeg|webp);base64,/.test(a.src))throw Error('项目图片格式无效');const s=validateSettings({...next,...a.transform});const img=await imageFrom(a.src);if(img.width*img.height>40000000)throw Error('项目中的图片过大');if(loaded.some(x=>x.id===a.id))throw Error('项目素材标识重复');loaded.push({id:a.id,name:a.name.slice(0,150),src:a.src,img,transform:Object.fromEntries(transforms.map(k=>[k,s[k]]))});}settings=next;assets=loaded;activeId=assets.find(a=>a.id===data.activeId)?.id??assets[0]?.id??null;presetOptions();renderAssets();refresh();}
$('project-input').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>100*1024*1024)throw Error('项目文件超过 100 MB');const data=JSON.parse(await file.text());checkpoint();await restore(data);toast('项目已打开');}catch(e){toast(e.message||'项目读取失败');}finally{$('project-input').value='';}};
$('undo').onclick=async()=>{if(!undoStack.length)return;const data=JSON.parse(undoStack.pop());await restore(data);$('undo').disabled=!undoStack.length;};
$('new-project').onclick=()=>{if(assets.length&&!confirm('新建项目将清空当前工作台。需要保留的话，请先保存项目文件。'))return;checkpoint();settings=defaults();assets=[];activeId=null;mock=false;presetOptions();renderAssets();refresh();toast('新的工作台已准备好');};
$('import-template').onclick=()=>$('template-input').click();
$('template-input').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>100000)throw Error('模板文件过大');const t=JSON.parse(await f.text());if(t.format!=='guzi-template'||t.version!==1)throw Error('请选择 guzi-template v1 JSON 模板，格式见项目说明');const s=validateSettings({...settings,type:t.type,width:t.width,height:t.height,bleed:t.bleed,safe:t.safe});checkpoint();settings=s;presetOptions();refresh();toast('制作规格已导入');}catch(e){toast(e.message);}finally{$('template-input').value='';}};
// Optional WebMCP registration uses the same actions and state as the visible UI.
const mc=document.modelContext;if(mc?.registerTool){try{mc.registerTool({name:'read_guzi_project',title:'查看谷子制作参数',description:'读取当前谷子的制作参数、素材数量和拼版结果，不读取图片内容。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(input&&Object.keys(input).length)throw Error('不接受参数');const s=current();let sheet;try{sheet=layoutSheet(s,Math.max(1,assets.length)*s.quantity);}catch(e){sheet={error:e.message};}return{settings:s,assetCount:assets.length,sheet};}});mc.registerTool({name:'configure_guzi_dimensions',title:'调整谷子尺寸',description:'调整当前谷子成品宽高和出血，立即更新编辑画布，不导出文件。',inputSchema:{type:'object',properties:{width:{type:'number',minimum:10,maximum:200},height:{type:'number',minimum:10,maximum:200},bleed:{type:'number',minimum:0,maximum:10}},required:['width','height','bleed'],additionalProperties:false},execute(input){if(!input||Object.keys(input).some(k=>!['width','height','bleed'].includes(k))||['width','height','bleed'].some(k=>typeof input[k]!=='number'))throw Error('尺寸参数无效');const next=validateSettings({...settings,...input});checkpoint();settings=next;refresh();return{width:settings.width,height:settings.height,bleed:settings.bleed};}});}catch(e){console.warn('WebMCP unavailable',e);}}
presetOptions();syncControls();draw();
(async()=>{restoring=true;try{const saved=await dbAction('readonly',store=>store.get('current'));if(saved){await restore(saved);$('save-state').textContent='已恢复本地项目';}else{const r=await fetch('sample.png');if(r.ok){const src=await fileData(await r.blob()),img=await imageFrom(src);assets=[{id:crypto.randomUUID(),name:'星野 · 原创示例.png',src,img,transform:{scale:100,rotation:0,x:0,y:8}}];activeId=assets[0].id;renderAssets();syncControls();draw();}}}catch(e){console.warn(e);$('save-state').textContent='可下载项目文件保存';}finally{restoring=false;scheduleSave();}})();
document.fonts.ready.then(draw);
